

import { useEffect, useState } from "react";
import { useImageSyncQueue } from "../../../ppm/cfimages/useImageSyncQueue";
import React from "react";
import { IMAGE_SYNC_QUEUE } from "../../../ppm/config/imageSyncQueueKey";
import { CF_IMAGES_REPO } from "../../../ppm/config/cfimages-repo";
import { CF_IMAGES_WORKER } from "../../../ppm/config/cfimages-worker-url";


const FILES_JSON_URL =`https://${CF_IMAGES_REPO}/images/files.json`;
const DELETE_IMAGE_ENDPOINT =  `${CF_IMAGES_WORKER}/api/delete-image`;

type FileRow = {
  id: string;
  path: string;
  name: string;
  meta?: Record<string, any>;
};

type FilesJson = Record<
  string,
  {
    path: string;
    name: string;
    meta?: Record<string, any>;
  }
>;

export default function TestImageTable() {
  const [rows, setRows] = useState<FileRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string>("");
  const [deletingId, setDeletingId] = useState<string>("");

  const [lockUI, setLockUI] = useState(false); // 🔥 added

  const { reconcile, queueDelete } = useImageSyncQueue();

  const formatDate = (id: string) => {
    const timestamp = Number(String(id).split("-")[0]);

    if (!Number.isFinite(timestamp)) return "-";

    const date = new Date(timestamp);

    if (Number.isNaN(date.getTime())) return "-";

    return new Intl.DateTimeFormat("en-US", {
      month: "2-digit",
      day: "2-digit",
      year: "numeric",
    }).format(date);
  };

  const buildBaseName = (row: FileRow) => {
    const dotIndex = row.name.lastIndexOf(".");
    return dotIndex >= 0 ? row.name.slice(0, dotIndex) : row.name;
  };

  const loadFiles = async () => {
    setLoading(true);
    setError("");

    try {
      const res = await fetch(FILES_JSON_URL+ `?v=${Date.now()}`, {
        method: "GET",
        headers: {
          Accept: "application/json",
        },
      });

      if (!res.ok) {
        throw new Error(`Failed to fetch files.json (HTTP ${res.status})`);
      }

      const json: FilesJson = await res.json();

      const parsed: FileRow[] = Object.entries(json || {}).map(([id, value]) => ({
        id,
        path: value?.path || "",
        name: value?.name || "",
        meta: value?.meta || {},
      }));

      parsed.sort((a, b) => {
        const aTime = Number(String(a.id).split("-")[0]);
        const bTime = Number(String(b.id).split("-")[0]);
        return bTime - aTime;
      });

      const { filteredRows } = reconcile(parsed);

      setRows(filteredRows);
    } catch (err: any) {
      setError(err?.message || "Failed to load files.json");
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (row: FileRow) => {
    const confirmed = window.confirm(`Delete ${row.name}?`);
    if (!confirmed) return;

    setDeletingId(row.id);
    setLockUI(true); // 🔥 added
    setError("");

    queueDelete(row.id);
    setRows((prev) => prev.filter((item) => item.id !== row.id));

    try {
      const baseName = buildBaseName(row);

      const res = await fetch(DELETE_IMAGE_ENDPOINT, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          baseName,
        }),
      });

      const text = await res.text();

      let json: any = null;
      try {
        json = JSON.parse(text);
      } catch {
        json = null;
      }

      if (!res.ok) {
        throw new Error(
          json?.error ||
            json?.githubResponse?.message ||
            json?.githubResponse?.error ||
            text ||
            `Delete failed (HTTP ${res.status})`
        );
      }

    
    } catch (err: any) {
   
      setRows((prev) => [row, ...prev].sort((a, b) => {
        const aTime = Number(String(a.id).split("-")[0]);
        const bTime = Number(String(b.id).split("-")[0]);
        return bTime - aTime;
      }));
      setError(err?.message || "Failed to delete image");
    } finally {
      await new Promise((r) => setTimeout(r, 3000)); // 🔥 added
      setDeletingId("");
      setLockUI(false); // 🔥 added
    }
  };

  useEffect(() => {
    loadFiles();
  }, []);

  return (
    <div
      style={{
        width: "100%",
        minHeight: "100vh",
        backgroundColor: "#ffffff",
        padding: 20,
        boxSizing: "border-box",
        fontFamily: "system-ui, Arial",
      }}
    >
      <div
        style={{
          width: "min(1200px, 100%)",
          margin: "0 auto",
          border: "1px solid #ddd",
          borderRadius: 12,
          padding: 18,
          boxShadow: "0 10px 30px rgba(0,0,0,0.06)",
          background: "#fff",
        }}
      >
        <div style={{ marginBottom: 16 }}>
          <h2 style={{ margin: 0, marginBottom: 6 }}>Images Table</h2>
          <div style={{ fontSize: 13, color: "#555" }}>
            Source: <code>{FILES_JSON_URL}</code>
          </div>
          <div style={{ fontSize: 13, color: "#555", marginTop: 6 }}>
            Delete endpoint: <code>{DELETE_IMAGE_ENDPOINT}</code>
          </div>
        </div>

        {loading ? (
          <div
            style={{
              padding: 24,
              border: "1px solid #eee",
              borderRadius: 10,
              background: "#fafafa",
              fontSize: 14,
              color: "#444",
            }}
          >
            Loading images...
          </div>
        ) : error ? (
          <div
            style={{
              padding: 24,
              border: "1px solid #f1c0c0",
              borderRadius: 10,
              background: "#fff5f5",
              fontSize: 14,
              color: "#a12626",
            }}
          >
            {error}
          </div>
        ) : (
          <div
            style={{
              width: "100%",
              overflowX: "auto",
              border: "1px solid #eee",
              borderRadius: 10,
            }}
          >
            <table
              style={{
                width: "100%",
                minWidth: 760,
                borderCollapse: "collapse",
                tableLayout: "fixed",
              }}
            >
              <thead>
                <tr style={{ background: "#fafafa" }}>
                  <th style={{ textAlign: "left", padding: "12px 14px", fontSize: 13, borderBottom: "1px solid #eee", width: 80 }}>n</th>
                  <th style={{ textAlign: "left", padding: "12px 14px", fontSize: 13, borderBottom: "1px solid #eee", width: 140 }}>Thumbnail</th>
                  <th style={{ textAlign: "left", padding: "12px 14px", fontSize: 13, borderBottom: "1px solid #eee", width: 180 }}>Date</th>
                  <th style={{ textAlign: "left", padding: "12px 14px", fontSize: 13, borderBottom: "1px solid #eee" }}>Name</th>
                  <th style={{ textAlign: "left", padding: "12px 14px", fontSize: 13, borderBottom: "1px solid #eee", width: 120 }}>Delete</th>
                </tr>
              </thead>

              <tbody>
                {rows.map((row, index) => {
                  const isDeleting = deletingId === row.id;

                  return (
                    <tr key={row.id}>
                      <td style={{ padding: "12px 14px", borderBottom: "1px solid #f2f2f2", fontSize: 14 }}>{index + 1}</td>

                      <td style={{ padding: "12px 14px", borderBottom: "1px solid #f2f2f2" }}>
                        <img src={row.path} alt={row.name} style={{ width: 100, height: 100, objectFit: "cover", borderRadius: 8, border: "1px solid #e5e5e5", background: "#f8f8f8" }} />
                      </td>

                      <td style={{ padding: "12px 14px", borderBottom: "1px solid #f2f2f2", fontSize: 14 }}>
                        {formatDate(row.id)}
                      </td>

                      <td style={{ padding: "12px 14px", borderBottom: "1px solid #f2f2f2", fontSize: 14 }}>
                        {row.name}
                      </td>

                      <td style={{ padding: "12px 14px", borderBottom: "1px solid #f2f2f2" }}>
                        <button
                          onClick={() => handleDelete(row)}
                          disabled={isDeleting}
                          style={{
                            border: "1px solid #ddd",
                            background: isDeleting ? "#f5f5f5" : "#fff",
                            borderRadius: 8,
                            padding: "8px 12px",
                          }}
                        >
                          {isDeleting ? "Deleting..." : "Delete"}
                        </button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* 🔥 overlay */}
      {lockUI && (
        <div
          style={{
            position: "fixed",
            inset: 0,
            background: "rgba(0,0,0,0.5)",
            zIndex: 9999,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <div
            style={{
              width: 50,
              height: 50,
              border: "5px solid #fff",
              borderTop: "5px solid transparent",
              borderRadius: "50%",
              animation: "spin 1s linear infinite",
            }}
          />
        </div>
      )}

<button
  onClick={() => {
    const data = JSON.parse(localStorage.getItem(IMAGE_SYNC_QUEUE) || "{}");
    console.log("🔥 IMAGE QUEUE:", data);
  }}
>
  Debug Queue
</button>


      <style>
        {`
          @keyframes spin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
          }
        `}
      </style>

      
    </div>
  );
}